<script setup lang="ts">
import { computed, onMounted, onBeforeUnmount, ref } from 'vue'
import { useRouter } from 'vue-router'
import SubingReplayChart from '@/components/subing/SubingReplayChart.vue'
import '@/styles/marketHome.css'
import MarketNavigation from '@/components/market/MarketNavigation.vue'
import { saveMarketHomeTab, type MarketHomeTab } from '@/utils/marketHomeTab'
const router=useRouter()
type Row=Record<string, any>
const runs=ref<Row[]>([]),run=ref(''),overview=ref<Row|null>(null),detail=ref<Row|null>(null),history=ref<Row[]>([])
const index=ref(0),offset=ref(0),error=ref(''),loading=ref(false)
const recordTab=ref('history'),step=ref(1),playing=ref(false),showEvidence=ref(false)
let playTimer:ReturnType<typeof setTimeout>|undefined
let playbackGeneration=0
function pause(){playbackGeneration++;playing.value=false;clearTimeout(playTimer)}
async function play(){if(playing.value){pause();return}playing.value=true;const epoch=++playbackGeneration;const tick=async()=>{if(!playing.value||epoch!==playbackGeneration)return;if(index.value>=(overview.value?.times.length??1)-1){pause();return}index.value=Math.min(index.value+step.value,overview.value!.times.length-1);offset.value=0;await seek();if(playing.value&&epoch===playbackGeneration)playTimer=setTimeout(tick,750)};void tick()}
let generation=0
onBeforeUnmount(()=>{generation++;pause()})
const base='/api/v1/research/subing-decision/runs'
async function get(url:string){const r=await fetch(url);if(!r.ok)throw new Error('回放结果不可用或校验失败，请检查已登记研究结果。');return r.json()}
async function select(){pause();const g=++generation;loading.value=true;error.value='';detail.value=null;overview.value=null;history.value=[];try{const o=await get(`${base}/${run.value}`);if(g!==generation)return;overview.value=o;index.value=o.times.length-1;offset.value=0;await seek()}catch(e){if(g===generation){error.value=String((e as Error).message);pause()}}finally{if(g===generation)loading.value=false}}
async function seek(){const g=++generation;loading.value=true;error.value='';try{const [d,h]=await Promise.all([get(`${base}/${run.value}/decision?index=${index.value}`),get(`${base}/${run.value}/history?index=${index.value}&offset=${offset.value}`)]);if(g!==generation)return;detail.value=d;history.value=h.items}catch(e){if(g===generation){error.value=String((e as Error).message);pause()}}finally{if(g===generation)loading.value=false}}
function move(n:number){pause();index.value=Math.max(0,Math.min((overview.value?.times.length??1)-1,index.value+n));offset.value=0;void seek()}
function home(tab:MarketHomeTab){saveMarketHomeTab(tab);void router.push('/market')}
async function loadRuns(){try{runs.value=(await get(base)).runs;run.value=runs.value[0]?.id??'';if(run.value)await select();else error.value='暂无已登记的完整焦煤回放。'}catch(e){error.value=(e as Error).message}}
onMounted(loadRuns)
const d=computed(()=>detail.value?.decision)
const labels:Record<string,string>={BAR_CLOSE:'普通完成Bar',DAY_END:'日终记录',NEXT_OPEN_AFTER_DAY_END:'下一开盘检查',NEXT_SESSION_OPEN_REVIEW:'记录持仓，等待下一开盘复核',EXIT_EXECUTION:'既有退出义务继续，等待后续模型成交',INTENT_EXECUTION:'等待后续模型执行',BREAK_CONFIRMATION:'等待连续三根收盘确认',REQUIRED_FACTS:'等待必要事实恢复',FRESH_POSITION:'等待新的合格位置',NEW_VALID_ENTRY:'等待新的有效入场机会',PROFIT_1R_TIER1_CLEAR:'首次1R目标触发清仓',PROFIT_1R_REDUCE:'首次1R目标触发减仓',FIXED_STOP:'固定初始止损',EMA_CLEAR:'EMA技术退出',ADD_PROTECTION:'加仓层价格保护',ORDINARY_REDUCTION:'技术减仓',ENVIRONMENT_FACTS_MISSING:'环境事实不足',TECHNICAL_FACTS_UNKNOWN:'技术事实不足',RECONCILIATION_REQUIRED:'等待对账事实',NEUTRAL:'中性',TREND_UP:'上涨趋势',TREND_DOWN:'下跌趋势',RANGE:'震荡',UNKNOWN:'未知',UP:'向上',DOWN:'向下',MIXED:'结构交错',BREAK_PENDING:'破位待确认',BREAK_CONFIRMED:'破位已确认',STRUCTURE_ENVELOPE:'近期结构包络',STRUCTURE_UPDATED:'结构已更新',REENTERED:'返回区间',BREAK_FAILED:'破位未成立',WAIT:'等待机会',HOLD:'持有',HOLD_NO_ADD:'持有，暂停加仓',WAIT_CONFIRMATION:'等待破位确认',RECORD_ONLY:'日终记录',EXIT_REQUIRED:'需要退出',EXIT_OBLIGATION:'处理清仓义务',REDUCE_OBLIGATION:'保护已有仓位',MANAGE_PENDING:'管理未决动作',CHECK_ENTRY_ELIGIBILITY:'首仓资格已通过',CHECK_ADD_ELIGIBILITY:'加仓资格已通过',LONG:'多头',SHORT:'空头',FLAT:'空仓',OPEN:'首仓',ADD:'加仓',CLOSE:'退出',REJECT:'未通过',CONFIRMED_RANGE_NO_FIRST_ENTRY:'确认震荡，等待趋势机会',REQUIRED_FACTS_UNAVAILABLE:'必要事实不足',ORIGINAL_ENTRY_FACTS_NOT_READY:'首仓条件未齐',REGIME_DISALLOWS_ADD:'环境不允许加仓',WAIT_FRESH_POSITION:'等待新的合格位置',NO_DUPLICATE_ACTION:'已有未决动作，等待处理',BREAK_UP_PENDING:'向上破位，等待确认',BREAK_DOWN_PENDING:'向下破位，等待确认',DAY_END_NO_NEW_EXPOSURE:'日终只记录，禁止新增',RANGE_OPEN_GROSS_LOSS:'震荡持仓开盘毛浮盈亏损',RANGE_THREE_NONPOSITIVE_DAYS:'连续三日非正且开盘仍非正',EXISTING_FULL_EXIT:'既有全清义务继续',EXISTING_REDUCTION:'既有减仓义务继续',ORIGINAL_ENTRY_FACTS_READY:'原首仓事实齐全',FRESH_POSITION_AND_ORIGINAL_ADD_FACTS_READY:'新位置与加仓条件齐全'}
function label(v:any){return labels[v]??v??'未知'}
function money(v:any){return v==null?'未知':Number(v).toFixed(2)}
function time(v:string){return new Date(v).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false})}
function jump(i:number){pause();index.value=i;offset.value=0;void seek()}
function reasonList(xs:string[]|undefined){return xs?.map(label).join('、')||'无'}
const versions:Record<string,string>={baseline:'原基线',previous_candidate:'既有v2候选',candidate:'统一候选'}
</script>
<template>
<div class="market-dashboard-page subing-workbench">
  <MarketNavigation active-tab="subing-decision" @market="home('market')" @messages="home('messages')" @simulation="home('simulation')"><template #actions><span class="boundary">历史回放 · 研究候选</span></template></MarketNavigation>
  <main>
    <header class="page-heading"><div><h1>苏冰决策</h1><span>焦煤 · 独立模型账户</span></div><label>历史窗口 <select v-model="run" aria-label="历史窗口" @change="select"><option v-for="r in runs" :key="r.id" :value="r.id">{{r.contract}}　{{r.since}} — {{r.through}}</option></select></label></header>
    <div v-if="error" role="alert" class="feedback">{{error}} <button @click="!run?loadRuns():overview?seek():select()">重试</button></div>
    <p v-if="!overview&&loading" role="status" class="feedback">正在加载历史回放…</p>
    <template v-if="overview">
      <section class="toolbar"><button aria-label="上一步" :disabled="loading||index===0" @click="move(-step)">◀ 上一步</button><button class="play" :disabled="index===overview.times.length-1&&!playing" @click="play">{{playing?'Ⅱ 暂停':'▶ 播放'}}</button><button aria-label="下一步" :disabled="loading||index===overview.times.length-1" @click="move(step)">下一步 ▶</button><select v-model.number="step" aria-label="回放步长"><option :value="1">逐分钟</option><option :value="30">每30根1m</option></select><input :value="index" type="range" min="0" :max="overview.times.length-1" aria-label="回放时刻" @input="jump(Number(($event.target as HTMLInputElement).value))"><strong>{{detail?time(detail.decision.at):'读取所选时刻…'}}</strong><span class="badge">{{d?label(d.phase):'加载中'}}</span></section>
      <p v-if="loading" role="status" class="loading-note">正在读取所选时刻，当前展示上次已确认快照…</p>
      <template v-if="d">
        <div class="workspace-grid" :aria-busy="loading">
          <section class="panel chart-panel"><header><h2>行情与结构</h2><span class="pill">30分钟</span><span class="muted">已完成Bar</span><div class="legend">紫色 EMA　蓝色 近期结构　橙色 初始保护</div></header><SubingReplayChart :key="run" :rows="detail!.chart" :stop="d.position.initial_stop" :target="d.position.profit_target"/><footer class="environment-strip"><span>日线 <b>{{label(d.daily_direction)}}</b></span><span>30m v2 <b>{{label(d.regime)}}</b></span><span>60m <b>{{label(d.structure?.hourly?.direction)}}</b><small>仅观察</small></span></footer></section>
          <aside><section class="panel decision-summary"><header><h2>当前决策</h2><span class="badge">{{label(d.phase)}}</span></header><div class="decision-content"><h3>{{label(d.demand)}}</h3><p class="decision-reason">{{label(d.reason)}}</p><dl><dt>主需求</dt><dd>{{label(d.demand)}}</dd><dt>新增许可</dt><dd>{{d.conditions.environment_allows_new?'环境允许，仍须信号及风险检查':'暂停新增'}}</dd><dt>下一检查</dt><dd>{{label(d.next_wait)}}</dd></dl><p class="notice" v-if="d.position.clear_reasons.length">{{reasonList(d.position.clear_reasons)}} · 退出义务继续</p><p class="notice" v-else-if="d.position.quantity">原持仓保护继续有效</p><p class="notice" v-if="d.conflict">v2与结构方向存在分歧，破位确认约束独立检查。</p></div></section>
          <section class="panel conditions"><header><h2>条件检查</h2><button class="text-button" @click="showEvidence=!showEvidence">{{showEvidence?'收起依据':'完整依据 →'}}</button></header><dl><dt>日线方向</dt><dd>{{label(d.daily_direction)}}</dd><dt>环境准入</dt><dd><span :class="['state',d.conditions.environment_allows_new?'pass':'wait']">{{d.conditions.environment_allows_new?'允许':'等待'}}</span></dd><dt>当根放量</dt><dd>{{d.conditions.frame?.volume_effective===true?'有效':d.conditions.frame?.volume_effective===false?'不满足':'未知'}}</dd><dt>风险事实</dt><dd><span :class="['state',d.conditions.risk_allows_new?'pass':'wait']">{{d.conditions.risk_allows_new?'通过':'不通过'}}</span></dd></dl></section></aside>
        </div>
        <section v-if="showEvidence" class="panel evidence"><header><h2>当前时刻完整依据</h2></header><div class="evidence-grid"><div><p>观察阶段：{{label(d.phase)}}</p><p>触发依据：{{reasonList(d.trigger_reasons)}}</p><p>支持依据：{{reasonList(d.supporting_reasons)}}</p><p>阻止理由：{{reasonList(d.blocking_reasons)}}</p><p>条件缺口：{{reasonList(d.condition_gaps)}}</p><p v-if="d.opening_review">开盘复核毛浮盈 {{money(d.opening_review.gross_remaining)}}元 · {{label(d.opening_review.reason)}} · {{time(d.opening_review.price_at)}}</p></div><div><p>近期结构：{{label(d.structure?.structure_direction)}} · {{label(d.structure?.phase)}} · 确认计数{{d.structure?.count??0}}/4（含突破根）</p><p>边界：{{money(d.structure?.lower)}} — {{money(d.structure?.upper)}}</p><p>EMA：{{money(d.conditions.frame?.ema21)}} · 30m角度：{{money(d.conditions.frame?.minute_angle)}}</p><p v-for="side in ['LONG','SHORT']" :key="side">{{label(side)}}交叉窗口：{{d.conditions.entry_windows[side]?.source_end?`${time(d.conditions.entry_windows[side].source_end)} · 已过${d.conditions.entry_windows[side].age}根`:'等待新交叉'}}</p><p>日线事实：{{d.daily_at?time(d.daily_at):'未知'}} · 60m：{{d.structure?.hourly?.at?time(d.structure.hourly.at):'未知'}}</p></div></div></section>
        <section class="panel position-panel"><header><h2>模型持仓</h2><span class="pill">独立模型账户</span><button class="text-button" @click="recordTab='layers'">逐层详情 →</button></header><div class="position-facts"><div><small>方向</small><strong>{{label(d.position.side??'FLAT')}}</strong></div><div><small>剩余仓位</small><strong>{{d.position.quantity}}<small>手</small></strong></div><div><small>当前毛浮盈</small><strong>{{money(d.gross_remaining)}}<small>元</small></strong></div><div><small>初始止损 / 1R目标</small><strong>{{money(d.position.initial_stop)}} / {{money(d.position.profit_target)}}</strong></div><div><small>未决动作</small><strong>{{d.position.pending?label(d.position.pending.kind):'无'}}</strong></div></div><p class="footnote">本时刻动作：{{d.actions.map((a:Row)=>label(a.kind)).join('、')||'无新增动作'}}。模型成交与真实账户成交独立；全部判断截至当前回放时刻。</p></section>
        <section class="panel records"><header class="records-header"><nav aria-label="回放记录"><button v-for="[key,title] in [['history','决策历史'],['fills','模型成交'],['layers','逐层持仓'],['performance','窗口绩效']]" :key="key" :aria-pressed="recordTab===key" @click="recordTab=key">{{title}}</button></nav><span class="muted">{{recordTab==='performance'?'完整窗口结果，包含游标之后':'仅显示当前时刻及之前'}}</span></header>
          <template v-if="recordTab==='history'"><table><thead><tr><th>时间</th><th>阶段与环境</th><th>主需求</th><th>关键依据</th></tr></thead><tbody><tr v-for="r in history" :key="r.at" tabindex="0" @click="jump(overview.times.indexOf(r.at))" @keydown.enter="jump(overview.times.indexOf(r.at))"><td>{{time(r.at)}}</td><td>{{label(r.phase)}} · {{label(r.regime)}}</td><td>{{label(r.demand)}}</td><td>{{label(r.reason)}}</td></tr></tbody></table><footer class="pagination"><span>{{offset+1}} — {{Math.min(offset+history.length,index+1)}} / {{index+1}}条观察</span><button :disabled="loading||offset===0" @click="pause();offset=Math.max(0,offset-30);seek()">较新</button><button :disabled="loading||offset+30>index" @click="pause();offset+=30;seek()">较早</button></footer></template>
          <template v-else-if="recordTab==='fills'"><table><thead><tr><th>成交时间</th><th>动作</th><th>价格</th><th>原因</th></tr></thead><tbody><tr v-for="(f,i) in detail!.fills" :key="i"><td>{{time(f.fill_at)}}</td><td>{{label(f.action)}}</td><td>{{money(f.price)}}</td><td>{{f.reasons.map(label).join('、')}}</td></tr></tbody></table><p v-if="!detail!.fills.length" class="empty">截至当前没有模型成交。</p></template>
          <template v-else-if="recordTab==='layers'"><table><thead><tr><th>层</th><th>方向</th><th>成本</th></tr></thead><tbody><tr v-for="l in d.position.layers" :key="l.layer_id"><td>{{label(l.kind)}} · {{l.layer_id}}</td><td>{{label(l.side)}}</td><td>{{money(l.price)}}</td></tr></tbody></table><p v-if="!d.position.quantity" class="empty">当前模型空仓。</p></template>
          <template v-else><p class="notice">完整窗口绩效包含当前游标之后的结果，不是当时决策依据。各窗口独立10万元，已见开发样本，非OOS。</p><table><thead><tr><th>版本</th><th>净损益</th><th>费用</th><th>成交数</th></tr></thead><tbody><template v-for="(v,k) in overview.summary" :key="k"><tr v-if="v.summary"><td>{{versions[k as string]??k}}</td><td>{{money(v.summary.net_pnl)}}</td><td>{{money(v.summary.fees)}}</td><td>{{v.fills}}</td></tr></template></tbody></table></template>
        </section>
      </template>
    </template>
  </main>
</div>
</template>
<style scoped>
.subing-workbench{background:#f8f9fb;--gy-detail-accent-soft:#fff4ee;--gy-border-focus:#ff6b2c}.subing-workbench :deep(.market-navigation){background:#fff}.subing-workbench :deep(.market-navigation__tabs button[aria-current=page]){color:#ff6b2c;background:#fff4ee;border-bottom:2px solid #ff6b2c;border-radius:0}.subing-workbench main{padding:0 24px 24px;max-width:1920px;margin:auto}.page-heading{display:flex;align-items:center;justify-content:space-between;min-height:76px;gap:16px}.page-heading>div{display:flex;gap:20px;align-items:center}h1{font-size:24px;font-weight:700;margin:0}h2{font-size:16px;margin:0;font-weight:650}h3{font-size:21px;margin:0 0 10px;line-height:1.45}.page-heading span,.muted,.footnote,.legend{color:#667085;font-size:12px}.boundary{font-size:12px;color:#667085}.subing-workbench select,.subing-workbench button{font:inherit}.subing-workbench select,.subing-workbench button:not(.text-button){min-height:32px;border:1px solid #ebedf0;background:#fff;border-radius:6px;padding:5px 12px;color:#20242b}.subing-workbench button:hover{background:#fff4ee;color:#ff6b2c}.subing-workbench button:disabled{opacity:.4;cursor:default}.toolbar{display:flex;gap:10px;align-items:center;background:#fff;padding:12px 16px;border:1px solid #ebedf0;border-radius:8px;margin-bottom:16px}.toolbar input{flex:1;min-width:60px;accent-color:#ff6b2c;cursor:pointer}.toolbar strong{font-size:13px;white-space:nowrap}.toolbar .play{color:#ff6b2c;background:#fff4ee;border-color:#ffddca}.badge,.pill{font-size:12px;border-radius:5px;padding:4px 9px;white-space:nowrap;background:#fff4ee;color:#be5827}.pill{background:#f2f2f7;color:#667085}.workspace-grid{display:grid;grid-template-columns:minmax(0,2fr) minmax(330px,1fr);gap:16px}.workspace-grid aside{display:grid;gap:14px;align-content:start}.panel{background:#fff;border:1px solid #ebedf0;border-radius:8px;min-width:0}.panel>header{display:flex;gap:12px;align-items:center;padding:12px 16px;border-bottom:1px solid #ebedf0;min-height:48px}.legend{margin-left:auto}.environment-strip{display:flex;justify-content:space-around;gap:12px;padding:15px;border-top:1px solid #ebedf0}.environment-strip b{margin-left:10px;font-weight:600}.environment-strip small{color:#667085;margin-left:8px}.decision-content{padding:16px}.decision-reason{margin:0 0 16px;color:#667085;line-height:1.7}.panel dl{display:grid;grid-template-columns:90px 1fr;margin:0;font-size:13px}.panel dt,.panel dd{padding:8px 0;border-bottom:1px solid #f1f2f5}.panel dd{margin:0;text-align:right}.notice{padding:9px 12px;background:#fff7ec;color:#9e611d;font-size:12px;border-radius:5px;line-height:1.6}.conditions dl{margin:0 16px 12px}.text-button{border:0;background:none;color:#ff6b2c;font-size:12px;margin-left:auto;padding:0;cursor:pointer}.state{padding:3px 12px;border-radius:4px;font-size:12px}.pass{background:#eaf8ee;color:#26854a}.wait{background:#fff4e1;color:#9d681a}.position-panel,.records,.evidence{margin-top:16px}.position-facts{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));padding:18px 16px;gap:16px}.position-facts>div{border-right:1px solid #ebedf0}.position-facts>div:last-child{border:0}.position-facts small{display:block;color:#667085;font-size:12px;margin-bottom:8px}.position-facts strong{font-size:20px;display:block}.position-facts strong small{display:inline;margin-left:4px;font-size:12px;font-weight:400}.position-facts>div:nth-child(4) strong{font-size:16px}.footnote{padding:0 16px 12px;margin:0}.evidence-grid{display:grid;grid-template-columns:1fr 1fr;padding:8px 16px;gap:24px;font-size:13px;line-height:1.6}.records-header{justify-content:space-between}.records nav{display:flex;gap:16px}.records nav button{border:0!important;border-radius:0!important;padding:8px 4px!important;background:none!important;font-weight:600}.records nav button[aria-pressed=true]{color:#ff6b2c;border-bottom:2px solid #ff6b2c!important}.records table{width:100%;border-collapse:collapse;font-size:13px;text-align:left}.records th{background:#f8f9fb;color:#667085;font-weight:500}.records th,.records td{padding:11px 16px;border-bottom:1px solid #ebedf0}.records tbody tr:hover{background:#fff6f0;cursor:pointer}.pagination{display:flex;gap:8px;justify-content:flex-end;align-items:center;padding:12px 16px}.pagination span{margin-right:auto;color:#667085;font-size:12px}.empty{padding:24px;text-align:center;color:#667085}.feedback{padding:16px;background:#fff4ee}.loading-note{font-size:12px;color:#9e611d;margin:-6px 0 10px} @media(max-width:1200px){.subing-workbench main{padding-inline:16px}.workspace-grid{grid-template-columns:minmax(0,1.6fr) minmax(300px,1fr)}.legend{display:none}.toolbar{gap:6px}.page-heading select{max-width:360px}}
</style>
